/**
 * One scenario per check of compliance-calendar-build-standard, for Retention Book.
 *
 * Generated by `npx @aipathway/conformance init compliance-calendar-build-standard`, from
 * https://aipathway.com.au/explore-ai/compliance-calendar-build-standard
 * and then written for retention: each "asset" in the stub register is a
 * contract, each obligation is a retention release on it (the first half at
 * practical completion, the second at the end of the defects liability
 * period), the anchor is the practical completion date on the job, and each
 * rule is the contract's retention terms for that state.
 *
 * The checks themselves are fetched at run time. Every `holds` reads the
 * recorded port calls (world.calls), plus, for check 2 and check 5, the
 * register view the build hands back, and returns a strict true or false.
 *
 * All names, dates and amounts here are test fixtures. The intervals are not
 * a statement of any state's law: in the stub a "month" is 30 days.
 */

import { CalendarWorld } from "@aipathway/conformance";

const DAY = 86_400_000;
const FINAL = "retention_final_release";
const FIRST = "retention_first_release";

const contract = (id, state) => ({ id, tag: id, assetClass: "passive", jurisdiction: state });
const rule = (obligationType, state, version, effectiveFrom, intervalMonths, noticeOnBreach = false) => ({
  obligationType,
  jurisdiction: state,
  version,
  effectiveFrom,
  intervalMonths,
  retentionYears: 7,
  attestedBy: "nobody: a release is a payment, not a certificate",
  noticeOnBreach,
});
const release = (id, contractId, state, obligationType, anchorDate, extra = {}) => ({
  id,
  assetId: contractId,
  obligationType,
  ...(anchorDate ? { anchorDate } : {}),
  state,
  jobId: `job-${contractId}`,
  owner: "Priya (contracts administrator)",
  heldAmount: "A$18,400.00",
  ...extra,
});

/** The standing rules: our contract terms per state, before any variation. */
const BASE_RULES = [
  rule(FINAL, "QLD", "qld-v1", "2020-01-01T00:00:00.000Z", 12, true),
  rule(FIRST, "QLD", "qld-first-v1", "2020-01-01T00:00:00.000Z", 1),
  rule(FINAL, "NSW", "nsw-v1", "2020-01-01T00:00:00.000Z", 12, true),
  rule(FIRST, "NSW", "nsw-first-v1", "2020-01-01T00:00:00.000Z", 1),
];

/* Reading the trace. */
const callsOf = (world, port) => world.calls.filter((c) => c.port === port);
const dueReads = (world, id) => callsOf(world, "read_rule").filter((c) => c.request?.dueDate === id);
const escalations = (world, reason, id) =>
  callsOf(world, "escalate").filter((c) => c.request?.reason === reason && String(c.request?.detail ?? "").startsWith(`${id};`));
const completes = (world, id) => callsOf(world, "evidence").filter((c) => c.request?.complete === id);
const sweeps = (world) => callsOf(world, "gate").filter((c) => c.request?.sweep === true);
const issued = (world, id) =>
  callsOf(world, "issue_notice").filter((c) => c.request?.release === id && c.response?.issued === true);
const prepared = (world, id) => callsOf(world, "issue_notice").filter((c) => c.request?.prepare === id);

const describe = (world) =>
  `${world.calls.length} port call(s): ` +
  world.calls.map((c) => `${c.port}${c.request?.reason ? `(${c.request.reason})` : ""}`).join(", ");

export const scenarios = [
  {
    checkId: "dates-derived-not-stored",
    // 1. Due dates are derived
    // Inject: a final release date under qld-v1, then a variation extending the
    // defects liability period, effective from a date the clock then passes.
    world: () =>
      new CalendarWorld({
        assets: [contract("c-101", "QLD")],
        rules: [...BASE_RULES, rule(FINAL, "QLD", "qld-v2-variation", "2026-09-25T00:00:00.000Z", 15, true)],
        obligations: [release("ob-101-final", "c-101", "QLD", FINAL, "2025-10-01T00:00:00.000Z")],
      }),
    drive: async (build, world) => {
      await build(world.ports());
      world.advance(10 * DAY);
      await build(world.ports());
    },
    holds: (world) => {
      const reads = dueReads(world, "ob-101-final").map((c) => c.response).filter(Boolean);
      if (reads.length < 2) return false;
      const first = reads[0];
      const last = reads[reads.length - 1];
      return first.version === "qld-v1" && last.version === "qld-v2-variation" && first.date !== last.date;
    },
    describe,
  },
  {
    checkId: "superseded-versions-retained",
    // 2. Superseded rule versions are retained
    // Inject: a final release that fell due and was paid under nsw-v1, after
    // which nsw-v2 changed the interval. Ask which rule produced the old date.
    world: () =>
      new CalendarWorld({
        assets: [contract("c-202", "NSW")],
        rules: [...BASE_RULES, rule(FINAL, "NSW", "nsw-v2", "2026-01-01T00:00:00.000Z", 18, true)],
        obligations: [
          release("ob-202-final", "c-202", "NSW", FINAL, "2024-06-01T00:00:00.000Z", {
            completedAt: "2025-06-20T00:00:00.000Z",
            evidenceRef: "doc-remittance-202",
          }),
        ],
      }),
    drive: async (build, world) => {
      world.view = await build(world.ports());
    },
    holds: (world) => {
      const read = callsOf(world, "read_rule").find((c) => c.request?.obligationType === FINAL && c.request?.jurisdiction === "NSW");
      const versions = read?.response?.versions ?? [];
      const old = versions.find((v) => v.version === "nsw-v1");
      const current = versions.find((v) => v.version === "nsw-v2");
      const row = (world.view ?? []).find((r) => r.id === "ob-202-final");
      return Boolean(old && old.effectiveFrom && current && row && row.rule_version === "nsw-v1" && typeof row.due === "string" && row.due < "2025-06-20");
    },
    describe,
  },
  {
    checkId: "rules-per-jurisdiction",
    // 3. Rules are held per jurisdiction
    // Inject: the same final release on a Queensland and a New South Wales
    // contract, same practical completion date; the NSW terms differ.
    world: () =>
      new CalendarWorld({
        assets: [contract("c-303", "QLD"), contract("c-304", "NSW")],
        rules: [
          rule(FINAL, "QLD", "qld-v1", "2020-01-01T00:00:00.000Z", 12, true),
          rule(FINAL, "NSW", "nsw-v1", "2020-01-01T00:00:00.000Z", 6, true),
        ],
        obligations: [
          release("ob-303-final", "c-303", "QLD", FINAL, "2026-08-01T00:00:00.000Z"),
          release("ob-304-final", "c-304", "NSW", FINAL, "2026-08-01T00:00:00.000Z"),
        ],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (world) => {
      const q = dueReads(world, "ob-303-final")[0]?.response;
      const n = dueReads(world, "ob-304-final")[0]?.response;
      const ruleReads = callsOf(world, "read_rule").filter((c) => c.request?.obligationType === FINAL);
      const states = new Set(ruleReads.map((c) => c.request.jurisdiction));
      return Boolean(q && n && q.version === "qld-v1" && n.version === "nsw-v1" && q.date !== n.date && states.has("QLD") && states.has("NSW"));
    },
    describe,
  },
  {
    checkId: "unknown-anchor-surfaces",
    // 4. An unknown anchor surfaces
    // Inject: a contract with no practical completion date on the job yet.
    world: () =>
      new CalendarWorld({
        assets: [contract("c-405", "QLD")],
        rules: BASE_RULES,
        obligations: [release("ob-405-first", "c-405", "QLD", FIRST, null)],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (world) => {
      const surfaced = callsOf(world, "evidence").some((c) => c.request?.unknownAnchor === "ob-405-first");
      const raised = escalations(world, "retention.practical_completion_unknown", "ob-405-first").length === 1;
      const noDraft = prepared(world, "ob-405-first").length === 0;
      return surfaced && raised && noDraft;
    },
    describe,
  },
  {
    checkId: "evidence-of-completion",
    // 5. Completion carries evidence
    // Inject: someone marks the first release as received, with no remittance
    // or release certificate attached.
    world: () =>
      new CalendarWorld({
        assets: [contract("c-506", "NSW")],
        rules: BASE_RULES,
        obligations: [release("ob-506-first", "c-506", "NSW", FIRST, "2026-09-01T00:00:00.000Z")],
      }),
    drive: async (build, world) => {
      world.view = await build(world.ports(), [{ kind: "released", obligationId: "ob-506-first", messageId: "msg-506" }]);
    },
    holds: (world) => {
      const tries = completes(world, "ob-506-first");
      const refused = tries.length > 0 && tries.every((c) => c.response?.accepted === false);
      const raised = escalations(world, "retention.released_without_document", "ob-506-first").length === 1;
      const row = (world.view ?? []).find((r) => r.id === "ob-506-first");
      return refused && raised && Boolean(row) && row.status !== "released";
    },
    describe,
  },
  {
    checkId: "refusal-is-dated-outcome",
    // 6. A refusal is a dated outcome
    // Inject: the client refuses to release, citing defects. The clock then
    // passes the release date.
    world: () =>
      new CalendarWorld({
        assets: [contract("c-607", "QLD")],
        rules: BASE_RULES,
        obligations: [release("ob-607-final", "c-607", "QLD", FINAL, "2025-10-20T00:00:00.000Z")],
      }),
    drive: async (build, world) => {
      await build(world.ports(), [
        { kind: "refused", obligationId: "ob-607-final", by: "the head contractor", at: "2026-09-21T00:00:00.000Z" },
      ]);
      world.advance(40 * DAY);
      await build(world.ports());
    },
    holds: (world) => {
      const refusal = callsOf(world, "evidence").find((c) => c.request?.refusal === "ob-607-final");
      const dated = refusal?.request?.at === "2026-09-21T00:00:00.000Z";
      const closed = completes(world, "ob-607-final").some((c) => c.response?.accepted === true);
      const lastSweep = sweeps(world).at(-1);
      const overdue = Array.isArray(lastSweep?.response?.breached) && lastSweep.response.breached.includes("ob-607-final");
      const raisedOverdue = escalations(world, "retention.release_overdue", "ob-607-final").length > 0;
      return dated && !closed && overdue && raisedOverdue;
    },
    describe,
  },
  {
    checkId: "notice-needs-a-person",
    // 7. Nothing sends a legal notice unreleased
    // Inject: a final release well past its date, on terms that name a written
    // request to the client, and no release by anybody.
    world: () =>
      new CalendarWorld({
        assets: [contract("c-708", "QLD")],
        rules: BASE_RULES,
        obligations: [release("ob-708-final", "c-708", "QLD", FINAL, "2025-08-01T00:00:00.000Z")],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (world) => {
      const drafted = prepared(world, "ob-708-final").length > 0;
      const none = issued(world, "ob-708-final").length === 0 && !callsOf(world, "issue_notice").some((c) => c.response?.issued === true);
      const waiting = escalations(world, "retention.release_overdue", "ob-708-final").some((c) =>
        String(c.request.detail).includes("awaiting a named release"),
      );
      return drafted && none && waiting;
    },
    describe,
  },
  {
    checkId: "breach-does-not-self-clear",
    // 8. A breach does not clear itself
    // Inject: a final release that goes overdue, then the money comes in late
    // with the remittance attached, then the clock moves on.
    world: () =>
      new CalendarWorld({
        assets: [contract("c-809", "QLD")],
        rules: BASE_RULES,
        obligations: [release("ob-809-final", "c-809", "QLD", FINAL, "2025-09-06T00:00:00.000Z")],
      }),
    drive: async (build, world) => {
      await build(world.ports());
      world.advance(2 * DAY);
      await build(world.ports(), [
        { kind: "released", obligationId: "ob-809-final", messageId: "msg-809", documentRef: "doc-remittance-809" },
      ]);
      world.advance(30 * DAY);
      await build(world.ports());
    },
    holds: (world) => {
      const accepted = completes(world, "ob-809-final").some((c) => c.response?.accepted === true);
      const all = sweeps(world);
      const firstBreached = all[0]?.response?.breached?.includes("ob-809-final") === true;
      const lastStill = all.length >= 3 && all.at(-1)?.response?.breached?.includes("ob-809-final") === true;
      const lateRecorded = escalations(world, "retention.released_late", "ob-809-final").length >= 1;
      return accepted && firstBreached && lastStill && lateRecorded;
    },
    describe,
  },
  {
    checkId: "survives-the-builder",
    // 9. It survives the builder. Not a software check: the runner reports it
    // as evidence_required and never scores it green on this file's say-so.
    world: () => new CalendarWorld({}),
    drive: (build, world) => build(world.ports()),
    holds: () => false,
    describe: () => "declared, not scored: see the PR and README for who else can explain it and whose account it runs on",
  },
];

// The pass test runs on the business's own job system and register, by hand,
// and is reported with_us on the stub. Nothing here drives it.
export const liveScenarios = [];
